CREATE DATABASE internet_usage
    WITH
    OWNER = postgres
    ENCODING = 'UTF8'
    CONNECTION LIMIT = -1
    IS_TEMPLATE = False;

-- Add temporal_tables extension to new database 
DROP EXTENSION IF EXISTS temporal_tables;
CREATE EXTENSION temporal_tables;

DROP TABLE IF EXISTS internet_usage CASCADE;
DROP TABLE IF EXISTS internet_usage_history;

CREATE TABLE internet_usage (
    entity TEXT NOT NULL,
    code TEXT NOT NULL,
    year INT NOT NULL,
    internet_share NUMERIC,
    sys_period tstzrange NOT NULL DEFAULT tstzrange(current_timestamp, NULL)
);

CREATE TABLE internet_usage_history (
    entity TEXT NOT NULL,
    code TEXT NOT NULL,
    year INT NOT NULL,
    internet_share NUMERIC,
    sys_period tstzrange NOT NULL
);

CREATE TRIGGER versioning_trigger
BEFORE INSERT OR UPDATE OR DELETE ON internet_usage
FOR EACH ROW
EXECUTE PROCEDURE versioning('sys_period', 'internet_usage_history', true);


BEGIN;
SELECT set_system_time('1990-01-01 00:00:00+08');

INSERT INTO internet_usage (entity, code, year, internet_share)
VALUES ('Afghanistan', 'AFG', 1990, 0.0);
COMMIT;

BEGIN;
SELECT set_system_time('1991-01-01 00:00:00+08');

DELETE FROM internet_usage
WHERE entity = 'Afghanistan' AND code = 'AFG';

INSERT INTO internet_usage (entity, code, year, internet_share)
VALUES ('Afghanistan', 'AFG', 1991, 0.0);
